"""Write an analyzed run's headline stats back into the WoW addon as a
plain Lua data file, so the addon can show the crunched numbers in-game.

A WoW addon is sandboxed -- no file or network access -- so the only way
results computed out here (route adherence, kick value, avoidable damage,
per-player breakdown) can reach it is a Lua file the game loads at
login/``/reload``. This is exactly how RaiderIO ships its
externally-generated data (``db/db_*.lua`` files listed in its ``.toc``,
"Generated by Raider.IO on ..."): a regular ``.toc``-loaded Lua file, NOT
a SavedVariable, so WoW reads it at load and never writes it back --
meaning an external write is never clobbered by a ``/reload`` (the way a
SavedVariable would be). The one unavoidable cost is that the addon only
re-reads the file on ``/reload``.

We emit ``PostmortemResults.lua``, which assigns a single global table the
addon's own ``Results.lua`` reads on load. The file is human-inspectable
on purpose (again like RaiderIO's), so it carries a generated-at header.
"""

from __future__ import annotations

import math
import time
from pathlib import Path
from typing import Any, Optional

RESULTS_FILENAME = "PostmortemResults.lua"
_GLOBAL = "PostmortemResults"


def _lua_string(s: str) -> str:
    """A double-quoted Lua string literal. WoW's Lua reads the file as
    UTF-8, so non-ASCII (a character/NPC name) passes through directly;
    only the characters that would break the literal or the file are
    escaped."""
    out = ['"']
    for ch in s:
        if ch == "\\":
            out.append("\\\\")
        elif ch == '"':
            out.append('\\"')
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\r":
            out.append("\\r")
        elif ch == "\t":
            out.append("\\t")
        elif ord(ch) < 0x20:
            # Zero-padded: Lua's decimal escape consumes up to three
            # digits, so "\\1" followed by a digit in the name swallows it.
            out.append(f"\\{ord(ch):03d}")
        else:
            out.append(ch)
    out.append('"')
    return "".join(out)


def to_lua_literal(value: Any, indent: int = 0) -> str:
    """Serialize a restricted Python value (dict / list / str / int /
    float / bool / None) to a Lua literal. Deliberately narrow: this only
    ever serializes the small, known ``build_results_payload`` structure,
    not arbitrary objects."""
    pad = "  " * indent
    child_pad = "  " * (indent + 1)

    if value is None:
        return "nil"
    if value is True:
        return "true"
    if value is False:
        return "false"
    if isinstance(value, str):
        return _lua_string(value)
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        if not math.isfinite(value):
            return "0"  # Lua has no portable literal for inf/nan; never emit one
        return repr(value)
    if isinstance(value, (list, tuple)):
        if not value:
            return "{}"
        items = [f"{child_pad}{to_lua_literal(v, indent + 1)}," for v in value]
        return "{\n" + "\n".join(items) + f"\n{pad}}}"
    if isinstance(value, dict):
        if not value:
            return "{}"
        items = []
        for k, v in value.items():
            key = f"[{_lua_string(str(k))}]"
            items.append(f"{child_pad}{key} = {to_lua_literal(v, indent + 1)},")
        return "{\n" + "\n".join(items) + f"\n{pad}}}"
    # Anything else is a bug in build_results_payload, not user data.
    raise TypeError(f"cannot serialize {type(value).__name__} to Lua")


def build_results_payload(report: dict[str, Any]) -> dict[str, Any]:
    """Pick the compact, high-value subset of a full analysis report that
    the addon can't compute itself -- route adherence, kick value,
    avoidable damage, the analyzed per-player breakdown -- plus the run
    headline. Deliberately small: this becomes a Lua file the game loads,
    not the whole report."""
    run = report.get("run") or {}
    forces = report.get("forces") or {}
    enemy_casts = report.get("enemy_casts") or {}
    death_cost = report.get("death_cost") or {}
    comparison = report.get("comparison") or {}
    timer = report.get("timer") or {}
    avoidable_damage = report.get("avoidable_damage") or {}
    dispel_efficiency = report.get("dispel_efficiency") or {}
    unplanned_pulls = report.get("unplanned_pulls") or {}

    # Spell ids the loaded avoidable-damage file actually tagged, gathered
    # from avoidable_damage's own already-filtered by_spell lists rather
    # than needing the raw AvoidableData object here -- used below to flag
    # whether a death's killing blow was an avoidable mechanic.
    avoidable_spell_ids = {
        sp.get("spell_id")
        for player_entry in avoidable_damage.get("by_player") or []
        for sp in player_entry.get("by_spell") or []
    }

    players = []
    for p in report.get("players") or []:
        players.append({
            "name": p.get("name") or "",
            "class": p.get("class"),
            "spec": p.get("spec"),
            "role": p.get("role"),
            "deaths": p.get("deaths") or 0,
            "interrupts": p.get("interrupts") or 0,
            "dps": p.get("dps") or 0,
            "hps": p.get("hps") or 0,
            "damage_done": p.get("damage_done") or 0,
            "healing_done": p.get("healing_done") or 0,
            "avoidable_damage_taken": p.get("avoidable_damage_taken") or 0,
        })

    payload: dict[str, Any] = {
        "generated_at": int(time.time()),
        "run": {
            "zone": run.get("zone") or "",
            "level": run.get("keystone_level"),
            "completed": bool(run.get("completed")),
            "timed": run.get("timed"),
            "duration_ms": run.get("duration_ms"),
            "wall_duration_s": run.get("wall_duration_s"),
        },
        "forces": {
            "pct": forces.get("pct"),
            "killed": forces.get("killed"),
            "required": forces.get("required"),
        },
        "kick_efficiency_pct": enemy_casts.get("kick_efficiency_pct"),
        "deaths": death_cost.get("deaths") or 0,
        "death_time_lost_s": death_cost.get("total_s"),
        "players": players,
    }
    # Optional sections: only present when the analysis actually had the
    # data (a route pasted, a par time resolved) -- mirror the report's
    # own "absent when not computed" shape rather than emitting nulls.
    if comparison.get("adherence_pct") is not None:
        payload["adherence_pct"] = comparison.get("adherence_pct")
    if timer:
        # par_ms/threshold_2_ms/threshold_3_ms are the real fields
        # _timer_summary emits (analysis/run_analyzer.py's own
        # _timer_summary); this used to read "diff_ms"/"timed" keys that
        # function never writes, so those addon-side fields were silently
        # always nil. margin_ms/threshold are only present once the run
        # actually finished (an abandoned run has no final time to grade).
        payload["timer"] = {
            "par_ms": timer.get("par_ms"),
            "threshold_2_ms": timer.get("threshold_2_ms"),
            "threshold_3_ms": timer.get("threshold_3_ms"),
            "margin_ms": timer.get("margin_ms"),
            "threshold": timer.get("threshold"),
        }

    # Missed-kick detail: only spells that actually got through at least
    # once are worth showing in-game (a spell that was always kicked has
    # nothing to report). Trimmed to the top 10 by got_through so the file
    # stays small on a dungeon with many enemy cast types.
    missed = [s for s in enemy_casts.get("spells") or [] if s.get("got_through")]
    missed.sort(key=lambda s: -s["got_through"])
    if missed:
        payload["enemy_casts"] = {
            "spells": [
                {
                    "spell_id": s.get("spell_id"),
                    "name": s.get("name"),
                    "kicked": s.get("kicked") or 0,
                    "got_through": s.get("got_through") or 0,
                }
                for s in missed[:10]
            ],
        }

    # Avoidable damage, top 3 spells per player who took any.
    avoidable_by_player = avoidable_damage.get("by_player") or []
    if avoidable_by_player:
        payload["avoidable_damage"] = {
            "by_player": [
                {
                    "name": p.get("name") or "",
                    "avoidable_damage_taken": p.get("avoidable_damage_taken") or 0,
                    "by_spell": [
                        {
                            "spell_id": sp.get("spell_id"),
                            "name": sp.get("name"),
                            "amount": sp.get("amount") or 0,
                        }
                        for sp in (p.get("by_spell") or [])[:3]
                    ],
                }
                for p in avoidable_by_player
            ],
        }

    if dispel_efficiency.get("overall_efficiency_pct") is not None:
        payload["dispel_efficiency"] = {
            "overall_efficiency_pct": dispel_efficiency.get("overall_efficiency_pct"),
            "schools": [
                {
                    "school": s.get("school"),
                    "applied": s.get("applied") or 0,
                    "dispelled": s.get("dispelled") or 0,
                    "efficiency_pct": s.get("efficiency_pct"),
                }
                for s in dispel_efficiency.get("schools") or []
                if s.get("efficiency_pct") is not None
            ],
        }

    if unplanned_pulls.get("total_off_route_mobs") or unplanned_pulls.get("total_untracked_mobs"):
        payload["unplanned_pulls"] = {
            "total_off_route_mobs": unplanned_pulls.get("total_off_route_mobs") or 0,
            "total_untracked_mobs": unplanned_pulls.get("total_untracked_mobs") or 0,
        }

    deaths_detail = []
    for d in report.get("deaths") or []:
        killing_blow = d.get("killing_blow") or {}
        spell_id = killing_blow.get("spell_id")
        deaths_detail.append({
            "t": d.get("t"),
            "player": d.get("player") or "",
            "spell": killing_blow.get("spell") or "Unknown",
            "avoidable": spell_id in avoidable_spell_ids if spell_id else False,
        })
    if deaths_detail:
        payload["deaths_detail"] = deaths_detail

    return payload


def render_results_lua(report: dict[str, Any]) -> str:
    """The full text of ``PostmortemResults.lua`` for a report."""
    payload = build_results_payload(report)
    stamp = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
    return (
        "-- PostmortemResults.lua\n"
        f"-- Generated by Postmortem on {stamp}. Do not edit by hand --\n"
        "-- this file is overwritten after every analyzed run, and read by\n"
        "-- the Postmortem addon on /reload. (A regular data file, not a\n"
        "-- SavedVariable, so /reload never clobbers it.)\n"
        f"{_GLOBAL} = {to_lua_literal(payload)}\n"
    )


def addon_dir_from_log_path(log_path: str | Path) -> Optional[Path]:
    """Derive the installed Postmortem addon directory from the configured
    combat-log path. A real WoW layout is
    ``.../World of Warcraft/<flavor>/Logs/WoWCombatLog.txt``, with the
    addon at ``.../World of Warcraft/<flavor>/Interface/AddOns/Postmortem``.
    Returns that directory only if it actually exists (the addon is
    installed) -- otherwise None, so a caller can skip the writeback
    quietly rather than creating stray folders.
    """
    log_path = Path(log_path)
    # <flavor>/Logs/WoWCombatLog.txt -> parents[0]=Logs, parents[1]=<flavor>;
    # the configured path may also be the Logs folder itself (what the
    # desktop app's "Choose Logs folder…" pickers store).
    logs_dir = log_path if log_path.name == "Logs" else log_path.parent
    if logs_dir.name != "Logs":
        return None
    flavor_dir = logs_dir.parent
    addon_dir = flavor_dir / "Interface" / "AddOns" / "Postmortem"
    return addon_dir if addon_dir.is_dir() else None


def write_addon_results(report: dict[str, Any], addon_dir: str | Path) -> Path:
    """Write ``PostmortemResults.lua`` into ``addon_dir`` and return its
    path. Raises ``OSError`` on a real write failure -- callers in the
    watch/analyze path wrap this best-effort so a failed writeback never
    breaks analysis or upload."""
    addon_dir = Path(addon_dir)
    dest = addon_dir / RESULTS_FILENAME
    dest.write_text(render_results_lua(report), encoding="utf-8")
    return dest
